import 'package:track_flowers_app/features/driver_orders/domain/entities/lat_lng_entity.dart';

/// Parsed result of a Google Directions API response for a single route.
class DirectionsResultModel {
  final List<LatLngEntity> points;
  final String distanceText;
  final String durationText;

  const DirectionsResultModel({
    required this.points,
    this.distanceText = '',
    this.durationText = '',
  });

  bool get isEmpty => points.isEmpty;

  /// Builds the model from the raw `/directions/json` payload.
  ///
  /// Returns an empty result when the API reports anything other than `OK`
  /// (e.g. `ZERO_RESULTS`, `REQUEST_DENIED`) so callers can fall back cheaply.
  factory DirectionsResultModel.fromJson(Map<String, dynamic> json) {
    final status = (json['status'] ?? '').toString();
    final routes = json['routes'];
    if (status != 'OK' || routes is! List || routes.isEmpty) {
      return const DirectionsResultModel(points: []);
    }

    final route = routes.first as Map<String, dynamic>;
    final overview = route['overview_polyline'];
    final encoded = overview is Map ? (overview['points'] ?? '').toString() : '';

    String distanceText = '';
    String durationText = '';
    final legs = route['legs'];
    if (legs is List && legs.isNotEmpty) {
      final leg = legs.first as Map<String, dynamic>;
      final distance = leg['distance'];
      final duration = leg['duration'];
      if (distance is Map) distanceText = (distance['text'] ?? '').toString();
      if (duration is Map) durationText = (duration['text'] ?? '').toString();
    }

    return DirectionsResultModel(
      points: decodePolyline(encoded),
      distanceText: distanceText,
      durationText: durationText,
    );
  }

  /// Decodes an [encoded] Google "Encoded Polyline Algorithm" string into a
  /// list of coordinates. Pure math — no network or SDK dependency.
  static List<LatLngEntity> decodePolyline(String encoded) {
    final points = <LatLngEntity>[];
    if (encoded.isEmpty) return points;

    int index = 0;
    final int len = encoded.length;
    int lat = 0;
    int lng = 0;

    while (index < len) {
      int shift = 0;
      int result = 0;
      int b;
      do {
        b = encoded.codeUnitAt(index++) - 63;
        result |= (b & 0x1f) << shift;
        shift += 5;
      } while (b >= 0x20);
      final int dLat = (result & 1) != 0 ? ~(result >> 1) : (result >> 1);
      lat += dLat;

      shift = 0;
      result = 0;
      do {
        b = encoded.codeUnitAt(index++) - 63;
        result |= (b & 0x1f) << shift;
        shift += 5;
      } while (b >= 0x20);
      final int dLng = (result & 1) != 0 ? ~(result >> 1) : (result >> 1);
      lng += dLng;

      points.add(LatLngEntity(lat: lat / 1e5, lng: lng / 1e5));
    }

    return points;
  }
}

import 'package:dio/dio.dart';
import 'package:injectable/injectable.dart';
import 'package:track_flowers_app/config/env/app_env.dart';
import 'package:track_flowers_app/features/driver_orders/data/models/directions_result_model.dart';
import 'package:track_flowers_app/features/driver_orders/domain/entities/lat_lng_entity.dart';

/// Thin client for the Google Directions API.
///
/// Uses its own [Dio] instance (not the app client) so no auth headers or the
/// backend base URL leak into the Google request. The API key is read from the
/// `.env` file via [AppEnv].
@lazySingleton
class DirectionsApiClient {
  static const String _baseUrl =
      'https://maps.googleapis.com/maps/api/directions/json';

  final Dio _dio;

  DirectionsApiClient() : _dio = Dio();

  /// Requests a single driving route between [origin] and [destination].
  ///
  /// Returns an empty [DirectionsResultModel] when the key is missing or the
  /// API does not return `OK`, letting the repository fall back to a free
  /// straight line instead of failing.
  Future<DirectionsResultModel> getRoute({
    required LatLngEntity origin,
    required LatLngEntity destination,
  }) async {
    final key = AppEnv.googleMapsKey;
    if (key.isEmpty) return const DirectionsResultModel(points: []);

    final response = await _dio.get(
      _baseUrl,
      queryParameters: {
        'origin': '${origin.lat},${origin.lng}',
        'destination': '${destination.lat},${destination.lng}',
        'mode': 'driving',
        'key': key,
      },
    );

    final data = response.data;
    if (data is Map<String, dynamic>) {
      return DirectionsResultModel.fromJson(data);
    }
    return const DirectionsResultModel(points: []);
  }
}

