/// Reads a `{lat, lng}` map either directly from [source] or from
/// `source[key]` when [key] is provided.
LatLngEntity? _readLocation(dynamic source, {String? key}) {
  if (source is! Map) return null;
  final raw = key == null ? source['location'] : source[key];
  if (raw is! Map) return null;
  final lat = (raw['lat'] as num?)?.toDouble();
  final lng = (raw['lng'] as num?)?.toDouble();
  if (lat == null || lng == null) return null;
  return LatLngEntity(lat: lat, lng: lng);
}

